    mouth = g.math('MAXIMUM', eq(row, 0.), eq(row, n))
    fixed = g.math('MAXIMUM', mouth, eq(col, 0.))
    band = g.setpos(grid.outputs['Mesh'], g.xyz(*point)); band = backend_weld.tag(g, band, key, True, mouth)
    for attr,value,kind in (('key',key,'FLOAT_VECTOR'),('fixed',fixed,'BOOLEAN'),('height_pinned',fixed,'BOOLEAN'),
            ('patch',owner+1.,'INT'),('field_valid',True,'BOOLEAN'),('v',1.-radial,'FLOAT'),
            ('t',c._read(g,records,'_lc_t',owner*(n+1.)+row),'FLOAT')):
        band = c._store(g, band, 'st_cq_'+attr, value, kind)
    wedge_geometry = None
    if half_profiles:
        zero_start, zero_end, collapsed = role(owner)
        mixed = 1.-eq(zero_start, zero_end)
        band = c._store(g, band, 'st_cq_pinned_height', edge_height(owner, row))
        band = cyclic.boundary._empty(g, band, (1.-collapsed)*(1.-mixed))
        samples = g.setpos(c._line(g, n+1.), g.xyz(*outer_at(owner, index)))
        for key, value, kind in (('st_ct_guide', g.xyz(*guide_at(owner, index)), 'FLOAT_VECTOR'),
                ('st_ct_edge_rise', edge_height(owner, index)-c._read(g, mouths, 'st_cj_datum', owner), 'FLOAT'),
                ('st_ct_valid', True, 'BOOLEAN')):
            samples = c._store(g, samples, key, value, kind)
        from . import curved_taper_quad_nodes
        wedge = g.node('GeometryNodeGroup', 'Direct three-block corner taper')
        wedge.node_tree = curved_taper_quad_nodes.build(multisided=True, curved_hub=True)
        for key, value in (('Samples', samples), ('Mouths', mouths), ('Owner', owner), ('Radial Count', m),
                ('Center X', n), ('Center Y', n), ('Zero Start', zero_start), ('Input Valid', safe*mixed)):
            g.bind(value, wedge.inputs[key])
        wedge_geometry = wedge.outputs['Geometry']

    iu = g.math('FLOOR', index/(half+1.)); iv = g.math('MODULO', index, half+1.); u=iu/half; v=iv/half
    p00=crown(owner); p10=guide_at(owner,half); p01=guide_at(previous,half)
    B=guide_at(owner,iu); L=guide_at(previous,n-iv); T=mix(p01,hub,u); R=mix(p10,hub,v)
    point=c._sub(c._add(mix(B,T,v),mix(L,R,u)),mix(mix(p00,p10,u),mix(p01,hub,u),v))
    u0=eq(iu,0.); u1=eq(iu,half); v0=eq(iv,0.); v1=eq(iv,half)
    for flag,p in ((u0,L),(u1,R),(v0,B),(v1,T)): point=c._pick(g,flag,p,point)
    key=g.xyz(-3.-owner,iu,iv)
    key=pick(u1,g.xyz(-1.,owner,iv),key,'VECTOR'); key=pick(v1,g.xyz(-1.,previous,iu),key,'VECTOR')
    key=pick(u1*v1,g.xyz(-2.,0.,0.),key,'VECTOR')
    key=pick(u0,cyclic.guide_key(g,previous,n-iv,n,sides),key,'VECTOR')
    key=pick(v0,cyclic.guide_key(g,owner,iu,n,sides),key,'VECTOR')
    grid=g.node('GeometryNodeMeshGrid','Direct Coons quad center block')
    g.bind(half+1.,grid.inputs['Vertices X']); g.bind(half+1.,grid.inputs['Vertices Y'])
    center=g.setpos(grid.outputs['Mesh'],g.xyz(*point)); center=backend_weld.tag(g,center,key,True,u0*v0)
    fixed = u0*v0
    if half_profiles:
        left_fixed = u0*role(previous)[2]; bottom_fixed = v0*role(owner)[2]
        fixed = g.math('MAXIMUM', fixed, g.math('MAXIMUM', left_fixed, bottom_fixed))
        pin = pick(left_fixed, edge_height(previous, n-iv), edge_height(owner, iu))
        center = c._store(g, center, 'st_cq_pinned_height', pin)
    for attr,value,kind in (('key',key,'FLOAT_VECTOR'),('fixed',fixed,'BOOLEAN'),('height_pinned',fixed,'BOOLEAN'),
                           ('patch',0,'INT'),('field_valid',True,'BOOLEAN')):
        center=c._store(g,center,'st_cq_'+attr,value,kind)
    meshes = [ri.outputs['Geometry'], band, center]
    if wedge_geometry is not None: meshes.append(wedge_geometry)
    g.bind(cyclic.boundary._join(g,*meshes),ro.inputs['Geometry'])
    geometry=backend_weld.weld(g,ro.outputs['Geometry'])
    if multicenter:
        from . import curved_multicenter_corner_nodes
        core=g.node('GeometryNodeGroup','Original physical-site centers and direct internal link quads')
        core.node_tree=curved_multicenter_corner_nodes.build()
        for key,value in (('Geometry',geometry),('Mouths',mouths),('Rows',n),('Input Valid',safe)):
            g.bind(value,core.inputs[key])
        geometry=core.outputs['Geometry'];safe*=c.V(g,core.outputs['Valid'])
    if transition_ring:
        from . import curved_corner_transition_ring_nodes
        ring=g.node('GeometryNodeGroup','Count transition around a separately sampled core')
        ring.node_tree=curved_corner_transition_ring_nodes.build()
        for key,value in (('Geometry',geometry),('Mouths',mouths),('Rows',n),
                          ('Cell Size',inp.outputs['Cell Size']),('Input Valid',safe)):
            g.bind(value,ring.inputs[key])
        geometry=ring.outputs['Geometry'];safe*=c.V(g,ring.outputs['Valid'])
    chart,row,col=g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'))
    is_band=g.math('GREATER_THAN',chart,.5); first=is_band*eq(row,0.); last=is_band*eq(row,n)
    is_crown=eq(chart,0.)*eq(col,0.)
    mouth_id=pick(is_crown,row,pick(first,chart-1.,pick(last,g.math('MODULO',chart,sides),-1.)))
    rank=pick(is_crown,m,pick(first,col,2.*m-col))
    half_profile = 0.; intervals = 2.*m
    if half_profiles:
        half_profile = c._read(g, mouths, 'st_cj_half', mouth_id, 'INT')
        intervals = (2.-g.math('ABSOLUTE', half_profile))*m
        rank = pick(is_crown, .5*(half_profile+1.)*intervals, pick(first, col, intervals-col))
    # Restore the complete input entrance coordinates after identity welding.
    old_key=pick(is_crown,g.xyz(0.,row,0.),g.xyz(chart,row/multiplier,col),'VECTOR')
    original,matched=lookup(old_key)
    geometry=g.setpos(geometry,pick(g.math('GREATER_THAN',mouth_id,-.5),original,g.position(),'VECTOR'))
    for key,value in (('st_cn_mouth',mouth_id),('st_cn_rank',rank)):
        geometry=c._store(g,geometry,key,value,'INT')
    rise=c._read(g,mouths,'st_cj_rise',mouth_id); datum=c._read(g,mouths,'st_cj_datum',mouth_id)
    pin=datum+cyclic.boundary._profile(g,rank/intervals,half_profile,rise)
    boundary_pin = c.named(g, 'st_cq_pinned_height') if half_profiles else 0.
    geometry=c._store(g,geometry,'st_cq_pinned_height',pick(g.math('GREATER_THAN',mouth_id,-.5),pin,boundary_pin))
    geometry=c._store(g,geometry,'st_cq_local_corner_pattern',True,'BOOLEAN')
    if grade_bands:
        geometry=c._store(g,geometry,'st_cq_band_boundary_bound',
            c._stat(g,records,c.named(g,'_lc_band_boundary_bound'),'Max'))
    if resample_collapsed:
        guide_side = row
        resampled = eq(chart, 0.)*(1.-is_crown)*c._read(g, records, '_lc_boundary_resampled', guide_side*(n+1.), 'BOOLEAN')
        geometry=c._store(g,geometry,'st_cq_boundary_resampled',resampled,'BOOLEAN')
        geometry=c._store(g,geometry,'st_cq_boundary_resampling_bound',c._stat(g,records,
            pick(c.named(g,'_lc_boundary_resampled','BOOLEAN'),c.named(g,'_lc_boundary_bound'),0.),'Max'))
    seams=c._stat(g,geometry,c.named(g,'_chart_seam_ok','BOOLEAN'))
    safe*=c._stat(g,geometry,pick(g.math('GREATER_THAN',mouth_id,-.5),matched,True,'BOOLEAN'))
    helper=_Nodes(g.g); cells=c.V(g,_positive_quads(helper,geometry.s,index.s,g.position().s))
    metric=g.node('GeometryNodeGroup','Corner-pattern shape admission'); metric.node_tree=quality.build()
    g.bind(geometry,metric.inputs['Geometry'])
    good=safe*seams*cells*(1.-g.math('GREATER_THAN',metric.outputs['Maximum Edge Ratio'],quality.MAX_EDGE_RATIO))
    plan=c._store(g,plan,'st_cq_count',n,'INT')
    for key,value in (('Geometry',cyclic.boundary._empty(g,geometry,good)),('Inspection Geometry',geometry),
            ('Samples',records),('Plan',plan),('Valid',good),('Inputs Valid',safe),('Cells Valid',cells),
            ('Seams Valid',seams),('Radial Count',m)):
        g.bind(value,out.inputs[key])
    if grade_bands:g.g['st_corner_radial_map']='power_or_geometric_v1'
    if batch_guides:g.g['st_corner_batched_guides']=1
    return g.g
